import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused kernel for tanh, scaling, and channel bias addition
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_tanh_scale_bias_kernel(const float* input, float* output, const float* bias, 
                                           float scaling_factor, int num_elements, int C, int H, int W) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index >= num_elements) return;

    int n = index / (C * H * W);
    int rem = index % (C * H * W);
    int c = rem / (H * W);

    float val = input[index];
    val = tanhf(val);
    val = val * scaling_factor + bias[c];
    output[index] = val;
}

torch::Tensor fused_tanh_scale_bias_cuda(torch::Tensor x, torch::Tensor bias, float scaling_factor) {
    auto output = torch::empty_like(x);
    int num_elements = x.numel();
    auto sizes = x.sizes();
    int C = sizes[1], H = sizes[2], W = sizes[3];

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    fused_tanh_scale_bias_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        bias.data_ptr<float>(),
        scaling_factor,
        num_elements,
        C, H, W
    );

    return output;
}
"""

fused_ops_cpp = "torch::Tensor fused_tanh_scale_bias_cuda(torch::Tensor x, torch::Tensor bias, float scaling_factor);"

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=fused_ops_cpp,
    cuda_sources=fused_ops_source,
    functions=['fused_tanh_scale_bias_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor, bias_shape, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.scaling_factor = scaling_factor
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.max_pool = nn.MaxPool2d(pool_kernel_size)
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_ops.fused_tanh_scale_bias_cuda(x, self.bias, self.scaling_factor)
        x = self.max_pool(x)
        return x
